  id: string;
  kind: string;
  title: string;
  detail: string;
  status: "pending" | "running" | "done" | "skipped" | "failed" | "blocked";
  message: string;
  started_at: string | null;
  finished_at: string | null;
};

export type DnsChange = {
  zone: string;
  type: string;
  name: string;
  say: string;
